template.query:
query SearchNodesAdvancedFiltering($content: String, $tableId: ID, $attributeFilters: [AttributeFilter!], $relationFilters: [RelationFilter!], $limit: Int = 20, $offset: Int = 0, $sortField: String = "createdAt", $sortDirection: SortDirection = DESC) {
  searchNodes(
    filter: {
      content: $content
      tableId: $tableId
      attributeFilters: $attributeFilters
      relationFilters: $relationFilters
    }
    pagination: {
      limit: $limit
      offset: $offset
    }
    sort: [
      {
        field: $sortField
        direction: $sortDirection
      }
    ]
  ) {
    nodes {
      id
      content
      table {
        id
        identifier
      }
      attributes {
        id
        value
        attribute {
          identifier
          name
          attributeType {
            name
            dataType
          }
        }
      }
      outgoingRelations {
        id
        relationType {
          identifier
          name
        }
        targetNode {
          id
          content
        }
      }
      incomingRelations {
        id
        relationType {
          identifier
          name
        }
        sourceNode {
          id
          content
        }
      }
      attributeCount
      relationCount
      createdAt
      updatedAt
    }
    totalCount
    hasNextPage
    hasPreviousPage
  }
}
